import{_ as e,c as s,o as r,a2 as a}from"./chunks/framework.DdOM6S6U.js";const g=JSON.parse('{"title":"PreRegisterController","description":"","frontmatter":{"sidebarPos":5,"sidebarTitle":"PreRegisterController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/auth/pre-register-controller.md","filePath":"system-reference/backend/http/controllers/auth/pre-register-controller.md","lastUpdated":1778363927000}'),t={name:"system-reference/backend/http/controllers/auth/pre-register-controller.md"},i=a(`<h1 id="preregistercontroller" tabindex="-1">PreRegisterController <a class="header-anchor" href="#preregistercontroller" aria-label="Permalink to &quot;PreRegisterController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/Auth/PreRegisterController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers\\Auth</code><br><strong>Extends</strong>: <code>Auth\\Controller</code><br><strong>Traits</strong>: <code>SendsEmailVerificationRegister</code></p><p>First step in the email-verified registration flow. Collects the user&#39;s email address, sends a verification link, and waits for the user to confirm before proceeding to account creation via <a href="./complete-register-controller">CompleteRegisterController</a>.</p><h2 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __construct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $app </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Calls the parent <code>Auth\\Controller</code> constructor.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="broker" tabindex="-1"><code>broker()</code> <a class="header-anchor" href="#broker" aria-label="Permalink to &quot;\`broker()\`&quot;">​</a></h3><p>Returns the register broker via <code>Register::broker()</code>.</p><h3 id="showemailform-view" tabindex="-1"><code>showEmailForm(): View</code> <a class="header-anchor" href="#showemailform-view" aria-label="Permalink to &quot;\`showEmailForm(): View\`&quot;">​</a></h3><p>Renders the pre-registration form where the user enters their email address. The form is built via <code>AuthFormBuilder::buildAuthViewData(&#39;pre_register&#39;)</code>.</p><h3 id="sendverificationlinkemail-request-request-from-trait" tabindex="-1"><code>sendVerificationLinkEmail(Request $request)</code> <em>(from trait)</em> <a class="header-anchor" href="#sendverificationlinkemail-request-request-from-trait" aria-label="Permalink to &quot;\`sendVerificationLinkEmail(Request $request)\` *(from trait)*&quot;">​</a></h3><p>Validates the email, sends a verification link through the register broker, and fires the <code>ModularousUserVerification</code> event on success.</p><p><strong>Response on success</strong>: redirects to the login page with a modal confirming the email was sent, or to a dedicated success page depending on the <code>MODULAROUS_USE_REGISTRATION_REDIRECT_WITH_MODAL</code> environment variable.</p><p><strong>Response on failure</strong>: returns a warning with the broker error message.</p><h3 id="showsuccessform-from-trait" tabindex="-1"><code>showSuccessForm()</code> <em>(from trait)</em> <a class="header-anchor" href="#showsuccessform-from-trait" aria-label="Permalink to &quot;\`showSuccessForm()\` *(from trait)*&quot;">​</a></h3><p>Renders a success page confirming the verification email was sent, with a button linking back to the login form.</p><h2 id="email-verified-registration-flow" tabindex="-1">Email-Verified Registration Flow <a class="header-anchor" href="#email-verified-registration-flow" aria-label="Permalink to &quot;Email-Verified Registration Flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. User visits registration page</span></span>
<span class="line"><span>   └─ RegisterController redirects to PreRegisterController (when email_verified_register = true)</span></span>
<span class="line"><span>        └─ showEmailForm() renders email-only form</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. User submits email</span></span>
<span class="line"><span>   └─ sendVerificationLinkEmail() sends signed verification link</span></span>
<span class="line"><span>        └─ Success modal or success page displayed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. User clicks verification link in email</span></span>
<span class="line"><span>   └─ CompleteRegisterController::showCompleteRegisterForm() renders full registration form</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. User completes registration</span></span>
<span class="line"><span>   └─ CompleteRegisterController::completeRegister() creates account</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./complete-register-controller">CompleteRegisterController</a> — second step: completes account creation after email verification</li><li><a href="./register-controller">RegisterController</a> — direct registration (when email verification is disabled)</li></ul>`,21),n=[i];function o(l,c,p,d,h,m){return r(),s("div",null,n)}const f=e(t,[["render",o]]);export{g as __pageData,f as default};
